<?php
namespace App\Services\Marketing;
use App\Models\{Order,PaymentWebhookEvent};use Illuminate\Support\Facades\DB;
/** Reconciles existing local evidence only; never contacts a payment provider. */
class MarketingOrderEvidence {
 public function reconcile(int $orderId):void{DB::transaction(function()use($orderId){$a=DB::table('marketing_order_attributions')->where('order_id',$orderId)->lockForUpdate()->first();if(!$a)return;$o=Order::with(['payments','refunds'])->find($orderId);if(!$o)return;$p=$o->payments->sortByDesc('id')->first(fn($p)=>in_array($p->status,['paid','partially_refunded','refunded'],true));if(!$p)return;$verified=false;$confirmedAt=null;if($p->gateway==='bank_transfer'&&$p->environment==='offline'&&$p->proof_status==='verified'&&$p->proof_reviewed_at){$verified=true;$confirmedAt=$p->proof_reviewed_at;}elseif($p->environment==='live'){foreach(PaymentWebhookEvent::where('order_payment_id',$p->id)->where('provider',$p->gateway)->where('environment',$p->environment)->whereNotNull('verified_at')->get() as $w){$d=$w->normalized_payload;$amount=null;$currency=null;if($p->gateway==='stripe'&&($d['type']??'')==='checkout.session.completed'&&data_get($d,'data.object.payment_status')==='paid'){$amount=data_get($d,'data.object.amount_total');$currency=data_get($d,'data.object.currency');}elseif($p->gateway==='billplz'&&($d['status']??'')==='paid'){$amount=$d['amount']??null;$currency='MYR';}elseif($p->gateway==='paypal'&&($d['event_type']??'')==='PAYMENT.CAPTURE.COMPLETED'){$value=data_get($d,'resource.amount.value');if(is_string($value)&&preg_match('/^([0-9]{1,10})\.([0-9]{2})$/D',$value,$m))$amount=(int)$m[1]*100+(int)$m[2];$currency=data_get($d,'resource.amount.currency_code');}if((is_int($amount)||is_string($amount))&&preg_match('/^[0-9]+$/D',(string)$amount)&&(int)$amount===(int)$p->amount&&is_string($currency)&&strtoupper($currency)===$p->currency){$verified=true;$confirmedAt=$w->verified_at;break;}}}
 if(!$verified||!$a->base_currency||$p->currency!==$a->base_currency||(int)$p->amount!==(int)$a->base_minor){if(!$a->paid_at)DB::table('marketing_order_attributions')->where('id',$a->id)->update(['state'=>'evidence_unconfirmed','updated_at'=>now()]);return;}$refund=(int)$o->refunds->where('status','completed')->sum('amount');abort_if($refund>$a->base_minor,422,'Refund evidence exceeds paid amount.'); $paid=$a->paid_at??$confirmedAt;DB::table('marketing_order_attributions')->where('id',$a->id)->update(['state'=>'paid','paid_at'=>$paid,'refunded_minor'=>$refund,'updated_at'=>now()]);});}
 public function sweep():int{$n=0;DB::table('marketing_order_attributions')->where('merchant_key',app(MarketingPosts::class)->merchant())->orderBy('id')->chunkById(100,function($rows)use(&$n){foreach($rows as $r){try{$this->reconcile($r->order_id);$n++;}catch(\Throwable){\Illuminate\Support\Facades\Log::warning('Marketing order evidence remains pending',['attribution_id'=>$r->id]);}}});return $n;}
}
